PRAGMA foreign_keys = ON;
-- Matematická analýza / lineární ODR 2. řádu s konstantními koeficienty.
-- Samostatný publikovaný test v master knihovně; studenti se přiřazují až z administrace.
INSERT OR IGNORE INTO self_check_tests
  (id, slug, version, title, description, subject, topic, level, estimated_minutes, status)
VALUES
  ('ode2-homogenni-partikularni-v1','ode2-homogenni-partikularni',1,
   'Diferenciální rovnice 2. řádu — homogenní a partikulární (36 úloh)',
   '[[calculator:Bez kalkulačky]]36 úloh / 71 bodů / 50–65 minut. Charakteristická rovnice, různé a násobné kořeny, komplexní kořeny, počáteční úlohy, metoda neurčitých koeficientů, rezonanční ansatz, skládání y_h+y_p a kontrola dosazením. Samostatné vysvětlení každé otázky; funguje i částečné odevzdání.',
   'Matematika','Lineární diferenciální rovnice 2. řádu','VŠ',60,'published');

INSERT OR IGNORE INTO self_check_questions
  (id,test_id,position,prompt,options_json,correct_answer,explanation,points)
VALUES
  ('ode2-homogenni-partikularni-v1-q01','ode2-homogenni-partikularni-v1','1','{"instruction": "Jaký je řád dané diferenciální rovnice?", "math": "y^{\\prime\\prime}-3y^{\\prime}+2y=0", "category": "01 / Typ rovnice a charakteristický polynom", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:1]]"}, {"id": "b", "label": "[[math:2]]"}, {"id": "c", "label": "[[math:3]]"}, {"id": "d", "label": "[[math:0]]"}]','b','Nejvyšší derivace je druhá; jde o rovnici 2. řádu.','1'),
  ('ode2-homogenni-partikularni-v1-q02','ode2-homogenni-partikularni-v1','2','{"instruction": "Která z rovnic je homogenní (ve smyslu pravé strany rovné nule)?", "math": "y^{\\prime\\prime}+4y=\\, ?", "category": "01 / Typ rovnice a charakteristický polynom", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:\\cos x]]"}, {"id": "b", "label": "[[math:0]]"}, {"id": "c", "label": "[[math:1]]"}, {"id": "d", "label": "[[math:e^x]]"}]','b','Homogenní lineární rovnice má na pravé straně nulu.','1'),
  ('ode2-homogenni-partikularni-v1-q03','ode2-homogenni-partikularni-v1','3','{"instruction": "Urči charakteristickou rovnici.", "math": "y^{\\prime\\prime}-5y^{\\prime}+6y=0", "category": "01 / Typ rovnice a charakteristický polynom", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:r^2-5r+6=0]]"}, {"id": "b", "label": "[[math:r^2+5r+6=0]]"}, {"id": "c", "label": "[[math:r-5=0]]"}, {"id": "d", "label": "[[math:6r^2-5r+1=0]]"}]','a','Dosazení y=e^{rx} vede k r²−5r+6=0.','1'),
  ('ode2-homogenni-partikularni-v1-q04','ode2-homogenni-partikularni-v1','4','{"instruction": "Urči kořeny charakteristické rovnice.", "math": "r^2-5r+6=0", "category": "01 / Typ rovnice a charakteristický polynom", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:1,\\ 6]]"}, {"id": "b", "label": "[[math:-2,\\ -3]]"}, {"id": "c", "label": "[[math:2,\\ 3]]"}, {"id": "d", "label": "[[math:-1,\\ 6]]"}]','c','Rozklad (r−2)(r−3)=0.','1'),
  ('ode2-homogenni-partikularni-v1-q05','ode2-homogenni-partikularni-v1','5','{"instruction": "Jaký diskriminant má rovnice?", "math": "r^2-4r+4=0", "category": "01 / Typ rovnice a charakteristický polynom", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:\\Delta=16]]"}, {"id": "b", "label": "[[math:\\Delta=0]]"}, {"id": "c", "label": "[[math:\\Delta=-4]]"}, {"id": "d", "label": "[[math:\\Delta=4]]"}]','b','Δ=b²−4ac=16−16=0.','1'),
  ('ode2-homogenni-partikularni-v1-q06','ode2-homogenni-partikularni-v1','6','{"instruction": "Jaké charakteristické kořeny má rovnice?", "math": "r^2+9=0", "category": "01 / Typ rovnice a charakteristický polynom", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:\\pm 3]]"}, {"id": "b", "label": "[[math:\\pm 9i]]"}, {"id": "c", "label": "[[math:\\pm 3i]]"}, {"id": "d", "label": "[[math:0,\\ 9]]"}]','c','r²=−9, tedy kořeny jsou ±3i.','1'),
  ('ode2-homogenni-partikularni-v1-q07','ode2-homogenni-partikularni-v1','7','{"instruction": "Vyber obecné řešení pro dva různé reálné kořeny.", "math": "r_1=1,\\quad r_2=2", "category": "02 / Homogenní řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:C_1e^x+C_2e^{2x}]]"}, {"id": "b", "label": "[[math:(C_1+C_2x)e^x]]"}, {"id": "c", "label": "[[math:C_1\\cos x+C_2\\sin x]]"}, {"id": "d", "label": "[[math:(C_1+C_2)e^x]]"}]','a','Dva různé reálné kořeny dávají dvě lineárně nezávislé exponenciály.','1'),
  ('ode2-homogenni-partikularni-v1-q08','ode2-homogenni-partikularni-v1','8','{"instruction": "Vyber správné obecné řešení pro dvojnásobný kořen.", "math": "(r-2)^2=0", "category": "02 / Homogenní řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:C_1e^{2x}+C_2e^{2x}]]"}, {"id": "b", "label": "[[math:(C_1+C_2x)e^{2x}]]"}, {"id": "c", "label": "[[math:C_1e^{2x}+C_2e^{-2x}]]"}, {"id": "d", "label": "[[math:C_1\\cos2x+C_2\\sin2x]]"}]','b','Druhá nezávislá funkce je xe^{2x}; dvě kopie e^{2x} by tvořily jen jednu konstantu.','1'),
  ('ode2-homogenni-partikularni-v1-q09','ode2-homogenni-partikularni-v1','9','{"instruction": "Vyber reálné obecné řešení pro komplexní kořeny.", "math": "r=-1\\pm2i", "category": "02 / Homogenní řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:e^{-x}(C_1\\cos2x+C_2\\sin2x)]]"}, {"id": "b", "label": "[[math:e^{-2x}(C_1\\cos x+C_2\\sin x)]]"}, {"id": "c", "label": "[[math:C_1e^{-x}+C_2e^{2x}]]"}, {"id": "d", "label": "[[math:C_1\\cos2x+C_2\\sin2x]]"}]','a','Pro α±iβ je y=e^{αx}(C₁cosβx+C₂sinβx).','1'),
  ('ode2-homogenni-partikularni-v1-q10','ode2-homogenni-partikularni-v1','10','{"instruction": "Vyber bázi prostoru řešení.", "math": "y^{\\prime\\prime}+4y^{\\prime}+4y=0", "category": "02 / Homogenní řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:e^{2x},\\ xe^{2x}]]"}, {"id": "b", "label": "[[math:e^{-2x},\\ xe^{-2x}]]"}, {"id": "c", "label": "[[math:e^{-2x},\\ e^{-2x}]]"}, {"id": "d", "label": "[[math:\\cos2x,\\ \\sin2x]]"}]','b','P(r)=(r+2)², dvojitý kořen −2.','1'),
  ('ode2-homogenni-partikularni-v1-q11','ode2-homogenni-partikularni-v1','11','{"instruction": "Jaké je obecné řešení?", "math": "y^{\\prime\\prime}=0", "category": "02 / Homogenní řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:C_1+C_2x]]"}, {"id": "b", "label": "[[math:C_1e^x+C_2e^{-x}]]"}, {"id": "c", "label": "[[math:C_1x^2+C_2]]"}, {"id": "d", "label": "[[math:C_1\\cos x+C_2\\sin x]]"}]','a','Dvojitý kořen r=0 vede na 1 a x; rovněž dvakrát integrujeme.','1'),
  ('ode2-homogenni-partikularni-v1-q12','ode2-homogenni-partikularni-v1','12','{"instruction": "Která funkce je obecným řešením?", "math": "y^{\\prime\\prime}+y^{\\prime}=0", "category": "02 / Homogenní řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:C_1+C_2e^{-x}]]"}, {"id": "b", "label": "[[math:C_1e^x+C_2e^{-x}]]"}, {"id": "c", "label": "[[math:C_1+C_2x]]"}, {"id": "d", "label": "[[math:e^{-x}(C_1+C_2x)]]"}]','a','P(r)=r(r+1), kořeny 0 a −1.','1'),
  ('ode2-homogenni-partikularni-v1-q13','ode2-homogenni-partikularni-v1','13','{"instruction": "Urči řešení počáteční úlohy.", "math": "y^{\\prime\\prime}-3y^{\\prime}+2y=0,\\quad y(0)=1,\\ y^{\\prime}(0)=0", "category": "03 / Počáteční podmínky", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:2e^x-e^{2x}]]"}, {"id": "b", "label": "[[math:e^x+e^{2x}]]"}, {"id": "c", "label": "[[math:-e^x+2e^{2x}]]"}, {"id": "d", "label": "[[math:e^x]]"}]','a','y=C₁e^x+C₂e^{2x}; C₁+C₂=1, C₁+2C₂=0. Vyjde C₁=2 a C₂=−1.','2'),
  ('ode2-homogenni-partikularni-v1-q14','ode2-homogenni-partikularni-v1','14','{"instruction": "Urči řešení při daných počátečních podmínkách.", "math": "y^{\\prime\\prime}+4y=0,\\quad y(0)=0,\\ y^{\\prime}(0)=2", "category": "03 / Počáteční podmínky", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:2\\sin2x]]"}, {"id": "b", "label": "[[math:\\sin2x]]"}, {"id": "c", "label": "[[math:\\cos2x]]"}, {"id": "d", "label": "[[math:2\\cos2x]]"}]','b','y=C₁cos2x+C₂sin2x. Z y(0)=0 plyne C₁=0 a y′(0)=2C₂=2.','2'),
  ('ode2-homogenni-partikularni-v1-q15','ode2-homogenni-partikularni-v1','15','{"instruction": "Vyber správné řešení.", "math": "y^{\\prime\\prime}+4y=0,\\quad y(0)=3,\\ y^{\\prime}(0)=0", "category": "03 / Počáteční podmínky", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:3\\sin2x]]"}, {"id": "b", "label": "[[math:\\cos2x]]"}, {"id": "c", "label": "[[math:3\\cos2x]]"}, {"id": "d", "label": "[[math:3e^{2x}]]"}]','c','C₁=3 a 2C₂=0.','2'),
  ('ode2-homogenni-partikularni-v1-q16','ode2-homogenni-partikularni-v1','16','{"instruction": "Najdi řešení počáteční úlohy s dvojnásobným kořenem.", "math": "y^{\\prime\\prime}-2y^{\\prime}+y=0,\\quad y(0)=0,\\ y^{\\prime}(0)=1", "category": "03 / Počáteční podmínky", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:e^x]]"}, {"id": "b", "label": "[[math:xe^x]]"}, {"id": "c", "label": "[[math:x^2e^x]]"}, {"id": "d", "label": "[[math:e^x+xe^x]]"}]','b','y=(C₁+C₂x)e^x. První podmínka C₁=0, druhá C₂=1.','2'),
  ('ode2-homogenni-partikularni-v1-q17','ode2-homogenni-partikularni-v1','17','{"instruction": "Jaký je tvar obecného řešení nehomogenní lineární rovnice?", "math": "L[y]=g(x)", "category": "04 / Partikulární řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:y=y_h+y_p]]"}, {"id": "b", "label": "[[math:y=y_h\\cdot y_p]]"}, {"id": "c", "label": "[[math:y=y_p\\text{ pouze}]]"}, {"id": "d", "label": "[[math:y=y_h-y_p\\text{ vždy}]]"}]','a','Superpozice: obecné řešení = obecné homogenní + jedno partikulární.','2'),
  ('ode2-homogenni-partikularni-v1-q18','ode2-homogenni-partikularni-v1','18','{"instruction": "Urči vhodný partikulární člen.", "math": "y^{\\prime\\prime}-3y^{\\prime}+2y=e^{3x}", "category": "04 / Partikulární řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:\\frac12e^{3x}]]"}, {"id": "b", "label": "[[math:e^{3x}]]"}, {"id": "c", "label": "[[math:3e^{3x}]]"}, {"id": "d", "label": "[[math:xe^{3x}]]"}]','a','P(3)=9−9+2=2, proto A=1/2.','2'),
  ('ode2-homogenni-partikularni-v1-q19','ode2-homogenni-partikularni-v1','19','{"instruction": "Pravá strana je v rezonanci s homogenním řešením. Vyber partikulární řešení.", "math": "y^{\\prime\\prime}-3y^{\\prime}+2y=e^x", "category": "04 / Partikulární řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:e^x]]"}, {"id": "b", "label": "[[math:-xe^x]]"}, {"id": "c", "label": "[[math:xe^{2x}]]"}, {"id": "d", "label": "[[math:\\frac12e^x]]"}]','b','Protože P(1)=0 a P′(1)=−1, pro Ax e^x dostaneme A=−1.','2'),
  ('ode2-homogenni-partikularni-v1-q20','ode2-homogenni-partikularni-v1','20','{"instruction": "Urči konstantní partikulární řešení.", "math": "y^{\\prime\\prime}-y=1", "category": "04 / Partikulární řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:1]]"}, {"id": "b", "label": "[[math:-1]]"}, {"id": "c", "label": "[[math:x]]"}, {"id": "d", "label": "[[math:0]]"}]','b','Dosadíme y_p=A: −A=1, tedy A=−1.','2'),
  ('ode2-homogenni-partikularni-v1-q21','ode2-homogenni-partikularni-v1','21','{"instruction": "Urči partikulární řešení vhodným polynomem.", "math": "y^{\\prime\\prime}-y=x", "category": "04 / Partikulární řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:x]]"}, {"id": "b", "label": "[[math:-x]]"}, {"id": "c", "label": "[[math:x^2]]"}, {"id": "d", "label": "[[math:-x-1]]"}]','b','Při y_p=Ax+B dostáváme −Ax−B=x, takže A=−1, B=0.','2'),
  ('ode2-homogenni-partikularni-v1-q22','ode2-homogenni-partikularni-v1','22','{"instruction": "Najdi konstantní partikulární řešení.", "math": "y^{\\prime\\prime}+4y=8", "category": "04 / Partikulární řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:8]]"}, {"id": "b", "label": "[[math:4]]"}, {"id": "c", "label": "[[math:2]]"}, {"id": "d", "label": "[[math:0]]"}]','c','y_p=A; 4A=8, tedy A=2.','2'),
  ('ode2-homogenni-partikularni-v1-q23','ode2-homogenni-partikularni-v1','23','{"instruction": "Najdi polynomické partikulární řešení.", "math": "y^{\\prime\\prime}-2y^{\\prime}+y=x", "category": "04 / Partikulární řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:x-2]]"}, {"id": "b", "label": "[[math:x+2]]"}, {"id": "c", "label": "[[math:2x+1]]"}, {"id": "d", "label": "[[math:x^2+2]]"}]','b','Při y_p=Ax+B je výraz L[y_p]=Ax+B−2A. A=1, B=2.','2'),
  ('ode2-homogenni-partikularni-v1-q24','ode2-homogenni-partikularni-v1','24','{"instruction": "Vypočti partikulární řešení exponenciálního buzení.", "math": "y^{\\prime\\prime}+y=e^{2x}", "category": "04 / Partikulární řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:e^{2x}]]"}, {"id": "b", "label": "[[math:\\frac15e^{2x}]]"}, {"id": "c", "label": "[[math:\\frac13e^{2x}]]"}, {"id": "d", "label": "[[math:xe^{2x}]]"}]','b','Dosadíme Ae^{2x}: (4+1)Ae^{2x}=e^{2x} ⇒ A=1/5.','2'),
  ('ode2-homogenni-partikularni-v1-q25','ode2-homogenni-partikularni-v1','25','{"instruction": "Proč nelze při rezonanci ponechat původní ansatz?", "math": "L[y_p]=e^{2x},\\quad y_h\\supset e^{2x}", "category": "04 / Partikulární řešení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:Protože~e^{2x}~má~příliš~velké~hodnoty]]"}, {"id": "b", "label": "[[math:Protože~e^{2x}~již~řeší~homogenní~rovnici]]"}, {"id": "c", "label": "[[math:Protože~partikulární~řešení~neexistuje]]"}, {"id": "d", "label": "[[math:Protože~pravá~strana~musí~být~polynom]]"}]','b','Když L[e^{2x}]=0, násobek e^{2x} nikdy nevytvoří nenulovou pravou stranu.','2'),
  ('ode2-homogenni-partikularni-v1-q26','ode2-homogenni-partikularni-v1','26','{"instruction": "Urči partikulární řešení mimo rezonanci.", "math": "y^{\\prime\\prime}+4y=\\cos x", "category": "05 / Rezonance a sinusové buzení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:\\frac13\\cos x]]"}, {"id": "b", "label": "[[math:\\cos x]]"}, {"id": "c", "label": "[[math:\\frac15\\cos x]]"}, {"id": "d", "label": "[[math:x\\sin x]]"}]','a','Dosazením A cos x získáme (4−1)A cos x=cos x. A=1/3.','3'),
  ('ode2-homogenni-partikularni-v1-q27','ode2-homogenni-partikularni-v1','27','{"instruction": "Najdi partikulární řešení v přesné rezonanci.", "math": "y^{\\prime\\prime}+4y=\\cos2x", "category": "05 / Rezonance a sinusové buzení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:\\frac14\\cos2x]]"}, {"id": "b", "label": "[[math:\\frac{x}{4}\\sin2x]]"}, {"id": "c", "label": "[[math:\\frac{x}{2}\\cos2x]]"}, {"id": "d", "label": "[[math:\\sin2x]]"}]','b','Při L=x→D²+4 platí L[x sin2x]=4 cos2x.','3'),
  ('ode2-homogenni-partikularni-v1-q28','ode2-homogenni-partikularni-v1','28','{"instruction": "Vyber partikulární řešení.", "math": "y^{\\prime\\prime}+9y=6\\sin3x", "category": "05 / Rezonance a sinusové buzení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:x\\cos3x]]"}, {"id": "b", "label": "[[math:-x\\cos3x]]"}, {"id": "c", "label": "[[math:\\sin3x]]"}, {"id": "d", "label": "[[math:2x\\sin3x]]"}]','b','L[x cos3x]=−6 sin3x; aby pravá strana byla +6 sin3x, volíme minus.','3'),
  ('ode2-homogenni-partikularni-v1-q29','ode2-homogenni-partikularni-v1','29','{"instruction": "Urči partikulární řešení při kombinaci sin a cos.", "math": "y^{\\prime\\prime}+2y^{\\prime}+2y=\\sin x", "category": "05 / Rezonance a sinusové buzení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:\\frac15\\sin x-\\frac25\\cos x]]"}, {"id": "b", "label": "[[math:\\sin x]]"}, {"id": "c", "label": "[[math:-\\frac25\\sin x+\\frac15\\cos x]]"}, {"id": "d", "label": "[[math:\\frac12\\cos x]]"}]','a','Z ansatzu A sin x+B cos x dostáváme A−2B=1, 2A+B=0. Tedy A=1/5, B=−2/5.','3'),
  ('ode2-homogenni-partikularni-v1-q30','ode2-homogenni-partikularni-v1','30','{"instruction": "Urči partikulární řešení pro dvojnásobnou rezonanci.", "math": "y^{\\prime\\prime}-4y^{\\prime}+4y=e^{2x}", "category": "05 / Rezonance a sinusové buzení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:xe^{2x}]]"}, {"id": "b", "label": "[[math:\\frac{x^2}{2}e^{2x}]]"}, {"id": "c", "label": "[[math:\\frac{x}{2}e^{2x}]]"}, {"id": "d", "label": "[[math:e^{2x}]]"}]','b','L=(D−2)² a L[x²e^{2x}]=2e^{2x}. Násobíme tedy 1/2.','3'),
  ('ode2-homogenni-partikularni-v1-q31','ode2-homogenni-partikularni-v1','31','{"instruction": "Který násobek x je nutný, pokud v P(r) je exponent pravé strany dvojnásobným kořenem?", "math": "P(r)=(r-\\lambda)^2,\\quad g=e^{\\lambda x}", "category": "05 / Rezonance a sinusové buzení", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:x^0]]"}, {"id": "b", "label": "[[math:x^1]]"}, {"id": "c", "label": "[[math:x^2]]"}, {"id": "d", "label": "[[math:x^3]]"}]','c','Pro kořen násobnosti m se standardní exponenciální ansatz násobí x^m.','3'),
  ('ode2-homogenni-partikularni-v1-q32','ode2-homogenni-partikularni-v1','32','{"instruction": "Jaký je Wronskián daných dvou řešení?", "math": "y_1=e^x,\\quad y_2=e^{2x}", "category": "06 / Kontrola a hlubší souvislosti", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:e^{3x}]]"}, {"id": "b", "label": "[[math:-e^{3x}]]"}, {"id": "c", "label": "[[math:0]]"}, {"id": "d", "label": "[[math:2e^{3x}]]"}]','a','W=y₁y₂′−y₁′y₂=2e^{3x}−e^{3x}=e^{3x} ≠0.','3'),
  ('ode2-homogenni-partikularni-v1-q33','ode2-homogenni-partikularni-v1','33','{"instruction": "Které tvrzení o jednom nalezeném partikulárním řešení je správné?", "math": "L[y_p]=g(x)", "category": "06 / Kontrola a hlubší souvislosti", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:Každé~jiné~partikulární~řešení~se~liší~o~řešení~homogenní~rovnice]]"}, {"id": "b", "label": "[[math:Partikulární~řešení~je~vždy~jediné]]"}, {"id": "c", "label": "[[math:Přičtením~y_h~změníme~pravou~stranu]]"}, {"id": "d", "label": "[[math:Každé~partikulární~řešení~musí~být~konstantní]]"}]','a','Jsou-li y_p a ỹ_p dvě partikulární řešení, L[y_p−ỹ_p]=g−g=0.','3'),
  ('ode2-homogenni-partikularni-v1-q34','ode2-homogenni-partikularni-v1','34','{"instruction": "Vyber správné řešení počáteční úlohy s buzením.", "math": "y^{\\prime\\prime}+4y=\\cos2x,\\quad y(0)=y^{\\prime}(0)=0", "category": "06 / Kontrola a hlubší souvislosti", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:\\frac{x}{4}\\sin2x]]"}, {"id": "b", "label": "[[math:\\frac14\\sin2x]]"}, {"id": "c", "label": "[[math:\\frac14\\cos2x]]"}, {"id": "d", "label": "[[math:\\cos2x]]"}]','a','Rezonanční partikulární řešení x sin(2x)/4 splňuje obě nulové počáteční podmínky.','3'),
  ('ode2-homogenni-partikularni-v1-q35','ode2-homogenni-partikularni-v1','35','{"instruction": "Vyber správné řešení počáteční úlohy mimo rezonanci.", "math": "y^{\\prime\\prime}+4y=\\cos x,\\quad y(0)=y^{\\prime}(0)=0", "category": "06 / Kontrola a hlubší souvislosti", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:\\frac13(\\cos x-\\cos2x)]]"}, {"id": "b", "label": "[[math:\\frac13\\cos x]]"}, {"id": "c", "label": "[[math:\\frac13\\sin2x]]"}, {"id": "d", "label": "[[math:\\cos x-\\cos2x]]"}]','a','y_p=cosx/3; homogenní korekce −cos2x/3 zajistí y(0)=0 a y′(0)=0.','3'),
  ('ode2-homogenni-partikularni-v1-q36','ode2-homogenni-partikularni-v1','36','{"instruction": "Který typ pravé strany obecně neleží ve standardní konečné tabulce neurčitých koeficientů?", "math": "y^{\\prime\\prime}+y=e^{x^2}", "category": "06 / Kontrola a hlubší souvislosti", "hint": "Urči typ kořenů nebo vhodný tvar řešení; potom zkontroluj dosazením."}','[{"id": "a", "label": "[[math:e^{x^2}]]"}, {"id": "b", "label": "[[math:e^{2x}]]"}, {"id": "c", "label": "[[math:\\sin x]]"}, {"id": "d", "label": "[[math:x^2]]"}]','a','Metoda neurčitých koeficientů typicky funguje pro konečné součty polynomů, exponenciál, sin a cos; pro e^{x²} použij variaci konstant.','3');
